function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawWorld(){const c=camera(),sx=screenShake?rand(-screenShake,screenShake):0,sy=screenShake?rand(-screenShake,screenShake):0;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,viewW,viewH);ctx.fillStyle='#252d26';ctx.fillRect(0,0,viewW,viewH);ctx.save();ctx.translate(-c.x+sx,-c.y+sy);
// worn concrete grid
